/**
 * Automated AI Pull Request Reviewer
 * Uses GitHub REST API + Google Gemini API (Free Tier)
 * Runs natively in Node.js 18+ without external npm dependencies.
 */

const fs = require('fs');

async function run() {
  const githubToken = process.env.GITHUB_TOKEN;
  const geminiApiKey = process.env.GEMINI_API_KEY;
  const eventPath = process.env.GITHUB_EVENT_PATH;

  if (!githubToken) {
    console.error('Missing GITHUB_TOKEN environment variable.');
    process.exit(1);
  }

  if (!geminiApiKey) {
    console.error('Missing GEMINI_API_KEY environment variable. Please add it to your GitHub Repository Secrets.');
    process.exit(1);
  }

  if (!eventPath || !fs.existsSync(eventPath)) {
    console.error('GITHUB_EVENT_PATH not found. This script must run inside a GitHub Action pull_request event.');
    process.exit(1);
  }

  const eventData = JSON.parse(fs.readFileSync(eventPath, 'utf8'));
  const pullRequest = eventData.pull_request;

  if (!pullRequest) {
    console.log('Not a pull request event. Skipping review.');
    return;
  }

  const repoFullName = eventData.repository.full_name;
  const prNumber = pullRequest.number;
  const prTitle = pullRequest.title;
  const prDescription = pullRequest.body || 'No description provided.';

  console.log(`Analyzing PR #${prNumber} on ${repoFullName}: "${prTitle}"`);

  // 1. Fetch Pull Request Diff from GitHub API
  const diffResponse = await fetch(`https://api.github.com/repos/${repoFullName}/pulls/${prNumber}`, {
    headers: {
      Authorization: `Bearer ${githubToken}`,
      Accept: 'application/vnd.github.v3.diff',
      'User-Agent': 'ai-pr-reviewer'
    }
  });

  if (!diffResponse.ok) {
    throw new Error(`Failed to fetch PR diff: ${diffResponse.status} ${diffResponse.statusText}`);
  }

  let diffText = await diffResponse.text();

  if (!diffText.trim()) {
    console.log('Empty diff. No changes to review.');
    return;
  }

  // Prevent token overflow on massive PRs (truncate to ~40,000 characters if huge)
  const MAX_DIFF_LENGTH = 40000;
  if (diffText.length > MAX_DIFF_LENGTH) {
    diffText = diffText.substring(0, MAX_DIFF_LENGTH) + '\n\n... [Diff truncated due to size limits]';
  }

  // 2. Call Google Gemini Flash API for Review
  console.log('Sending diff to Gemini AI for review...');
  const prompt = `You are an expert senior software engineer and security auditor conducting an automated code review on a GitHub Pull Request.

PR Title: ${prTitle}
PR Description: ${prDescription}

Here is the Git Diff:
\`\`\`diff
${diffText}
\`\`\`

Please provide a thorough, structured, and constructive code review in GitHub Markdown format with the following sections:
1. 📋 **Summary of Changes**: Brief 2-3 sentence overview of what this PR does.
2. 🚨 **Bugs & Edge Cases**: Point out any logic errors, missing null/error handling, or potential runtime crashes.
3. 🔒 **Security & Credentials**: Check for hardcoded secrets, injection flaws, unsafe input, or vulnerability risks.
4. ⚡ **Performance & Optimization**: Note any memory leaks, inefficient loops, or unnecessary computations.
5. 💡 **Suggested Improvements**: Provide specific code snippets showing how to fix any identified issues.
6. 🏁 **Verdict**: [LGTM (Looks Good To Me) / Needs Minor Improvements / Changes Requested]

Keep feedback concise, polite, and directly actionable. Mention file names and line numbers where appropriate.`;

  const geminiEndpoint = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${geminiApiKey}`;

  const geminiResponse = await fetch(geminiEndpoint, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      contents: [{
        parts: [{ text: prompt }]
      }],
      generationConfig: {
        temperature: 0.2,
        maxOutputTokens: 2048
      }
    })
  });

  if (!geminiResponse.ok) {
    const errorText = await geminiResponse.text();
    throw new Error(`Gemini API Error: ${geminiResponse.status} - ${errorText}`);
  }

  const geminiResult = await geminiResponse.json();
  const reviewMarkdown = geminiResult.candidates?.[0]?.content?.parts?.[0]?.text;

  if (!reviewMarkdown) {
    throw new Error('No review content generated by Gemini.');
  }

  const finalComment = `### 🤖 Automated AI Code Review\n\n${reviewMarkdown}\n\n---\n*Powered by Gemini 2.5 Flash • Free Automated PR Reviewer*`;

  // 3. Post the review as a comment on the Pull Request
  console.log('Posting review comment to PR...');
  const commentResponse = await fetch(`https://api.github.com/repos/${repoFullName}/issues/${prNumber}/comments`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${githubToken}`,
      Accept: 'application/vnd.github.v3+json',
      'Content-Type': 'application/json',
      'User-Agent': 'ai-pr-reviewer'
    },
    body: JSON.stringify({ body: finalComment })
  });

  if (!commentResponse.ok) {
    const err = await commentResponse.text();
    throw new Error(`Failed to post comment to PR: ${commentResponse.status} - ${err}`);
  }

  console.log('✅ Successfully posted AI review comment to PR #' + prNumber);
}

run().catch(err => {
  console.error('❌ Error during AI PR review:', err);
  process.exit(1);
});
